# Find magic sequence of length 7
# x[i] = count of i in the sequence

solutions = []

# x[i] >= 0, sum x[i] = 7, sum i*x[i] = 7
# Also, for each i, exactly x[i] of the x[j] must equal i.

# Let's brute force with some pruning
# Since sum x[i] = 7 and sum i*x[i] = 7, we can iterate over possible values

for x0 in range(8):
    for x1 in range(8 - x0):
        for x2 in range(8 - x0 - x1):
            for x3 in range(8 - x0 - x1 - x2):
                for x4 in range(8 - x0 - x1 - x2 - x3):
                    for x5 in range(8 - x0 - x1 - x2 - x3 - x4):
                        x6 = 7 - x0 - x1 - x2 - x3 - x4 - x5
                        if x6 < 0:
                            continue
                        # Check weighted sum
                        weighted = 1*x1 + 2*x2 + 3*x3 + 4*x4 + 5*x5 + 6*x6
                        if weighted != 7:
                            continue

                        seq = [x0, x1, x2, x3, x4, x5, x6]

                        # Verify: for each i, count of i in seq equals x[i]
                        valid = True
                        for i in range(7):
                            if seq.count(i) != seq[i]:
                                valid = False
                                break

                        if valid:
                            solutions.append(seq)

print(f"Found {len(solutions)} solutions:")
for sol in solutions:
    print(sol)
